int main(){try{MeetingFixture f;auto early=f.common.tick();f.common.state().identity.tick=2;need(!preview_visit_appointment_meeting(f.common,f.interactions,f.dialogues,f.access,f.appointments,f.state,f.meeting,"sender",{f.invitation_id,f.acceptance_id}).ok,"frozen earliest date cannot be bypassed");f.common.state().identity.tick=early;auto action=f.start();need(f.full(),"active exact original action cold validates");auto running=query_visit_appointment_meeting_action(f.common,f.meeting,"sender",action);need(running.ok&&running.value&&running.value->status=="active"&&running.value->remaining_ticks==1,"Continue only reads same actual one-period active action");need(!query_visit_appointment_meeting_action(f.common,f.meeting,"recipient",action).value,"provider cannot continue another actors initiator action");auto finished=f.finish(action);need(finished.success&&f.full(),"real one-period meeting fulfilled and released");const auto& bound=*f.meeting.finished.find(finished.fact_id)->player_receipt;const auto* actual=f.common.state().results.find(bound.request_actor_id+":"+std::to_string(bound.request_sequence));need(actual&&*actual&&query_visit_appointment_meeting_completion(f.common,f.meeting,"sender",action,*(*actual)->details,f.common.tick(),(*actual)->result_id).ok,"Continue exact real completion result matches this action");need(!query_visit_appointment_meeting_completion(f.common,f.meeting,"sender",action,*(*actual)->details,f.common.tick(),"result:1").ok,"another old result cannot satisfy current meeting completion");auto json=encode_visit_appointment_meetings(f.meeting);auto restored=decode_visit_appointment_meetings(json);need(restored.ok&&compare_boundary(json,encode_visit_appointment_meetings(restored.value)).exact(),"independent meeting JSON exact roundtrip");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);auto copy=f.meeting;need(visit_visit_appointment_meetings_checkpoint(writer,copy).ok&&writer.finish().ok,"independent meeting typed visitor writes");
 auto original=f.meeting;f.meeting.finished.find(finished.fact_id)->tick++;need(!f.full(),"completion tick must equal original start plus exactly one period");f.meeting=original;f.common.state().results=OrderedTable<std::shared_ptr<const CommitResult>>{};f.common.state().history.clear();need(f.full(),"actual meeting permanent result survives cache cropping");f.meeting.started.find(f.meeting.started.order().front())->player_receipt.reset();need(!f.full(),"cropped cache cannot excuse missing real start binding");f.meeting=original;
 MeetingFixture departed;auto da=departed.start();auto failed=departed.finish(da,true);need(!failed.success&&failed.reason=="VisitAppointmentMeetingChanged"&&departed.full(),"lost actual session records exact failed completion and releases both people");auto interrupted=query_visit_appointment_meeting_action(departed.common,departed.meeting,"sender",da);need(interrupted.ok&&interrupted.value&&interrupted.value->status=="interrupted"&&interrupted.value->reason=="VisitAppointmentMeetingChanged","Continue failure read preserves exact original departure reason without spelling drift");
 MeetingFixture cancelled;cancelled.private_meet("cancel");auto q=preview_visit_appointment_meeting_cancel(cancelled.common,cancelled.interactions,cancelled.dialogues,cancelled.access,cancelled.appointments,cancelled.state,cancelled.meeting,"sender",{cancelled.invitation_id,cancelled.acceptance_id});need(q.ok,"both original people explicitly cancel in real matching say");auto before=cancelled.meeting;auto id=cancel_visit_appointment_meeting_in_candidate(cancelled.common,cancelled.interactions,cancelled.dialogues,cancelled.access,cancelled.appointments,cancelled.state,cancelled.meeting,q.value);need(id.ok,"actual cancellation source written");ReceiptDetails details;InteractionEffect effect;effect.settlement_result=id.value;details.data=effect;cancelled.bind(before,"cancel_visit_appointment",details);need(cancelled.full(),"cancel source and exact actual result cold validate");cancelled.private_meet("meet");need(!preview_visit_appointment_meeting(cancelled.common,cancelled.interactions,cancelled.dialogues,cancelled.access,cancelled.appointments,cancelled.state,cancelled.meeting,"sender",{cancelled.invitation_id,cancelled.acceptance_id}).ok,"cancelled invitation never restarts");
 // 两次原三源写者与实际终结，不以当前空Action倒补旧承诺解除时刻。
 MeetingFixture complete_again;auto ca=complete_again.start();complete_again.finish(ca);auto cm=complete_again.original();complete_again.meet("recipient","offer_invitation");auto ci=complete_again.commit("recipient",OfferVisitAppointment{"invitation",cm});need(ci.ok&&complete_again.full(),"real earlier fulfillment permits a later overlapping own promise");
 auto second_message=cancelled.original();cancelled.meet("recipient","offer_invitation");auto second_invitation=cancelled.commit("recipient",OfferVisitAppointment{"invitation",second_message});need(second_invitation.ok&&cancelled.full(),"real earlier mutual cancellation releases original commitment for a new offer");
 auto cancellation_sources=cancelled.meeting.cancelled;cancelled.meeting.cancelled=OrderedTable<VisitAppointmentMeetingCancelled>{};need(!validate_visit_appointment_commitment_history(cancelled.common,cancelled.prior,cancelled.state,cancelled.meeting).ok,"new overlapping promise requires the real earlier cancellation source");cancelled.meeting.cancelled=cancellation_sources;
 auto old_tick=cancelled.meeting.cancelled.find(id.value)->contact.tick;cancelled.meeting.cancelled.find(id.value)->contact.tick=cancelled.common.tick()+1;need(!validate_visit_appointment_commitment_history(cancelled.common,cancelled.prior,cancelled.state,cancelled.meeting).ok,"future cancellation cannot release a promise already made at current boundary");cancelled.meeting.cancelled.find(id.value)->contact.tick=old_tick;

 std::cout<<checks<<" actual meeting source checks; original World phase and GUI deferred\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
